// Writes app/data/assets.js (static/, fonts/, locales/) and app/data/example.js (example/) for the
// offline app, which cannot fetch its own files from file:// URLs. The repo files stay the source.
// Run: node tools/make-app-data.mjs          (rewrite)
//      node tools/make-app-data.mjs --check  (exit 1 when the generated files are out of date)
import { readFileSync, readdirSync, statSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../', import.meta.url));

function files(dir, prefix = '') {
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) out.push(...files(full, `${prefix}${name}/`));
    else out.push([prefix + name, full]);
  }
  return out;
}

const b64 = (full) => readFileSync(full).toString('base64');
const table = (dir) => files(join(ROOT, dir)).map(([k, full]) => `  ${JSON.stringify(k)}: ${JSON.stringify(b64(full))},`).join('\n');

function assets() {
  const locales = readdirSync(join(ROOT, 'locales')).filter((n) => n.endsWith('.json')).sort()
    .map((n) => `  ${JSON.stringify(n.slice(0, -5))}: ${JSON.stringify(JSON.parse(readFileSync(join(ROOT, 'locales', n), 'utf8')))},`).join('\n');
  return `// Generated by tools/make-app-data.mjs from static/, fonts/ and locales/; do not edit.
window.FC_ASSETS = {static: {
${table('static')}
}, fonts: {
${table('fonts')}
}, locales: {
${locales}
}};
`;
}

function example() {
  return `// Generated by tools/make-app-data.mjs from example/; do not edit.
window.FC_EXAMPLE = {
${table('example')}
};
`;
}

const outputs = { 'app/data/assets.js': assets(), 'app/data/example.js': example() };
const check = process.argv.includes('--check');
let stale = [];
for (const [path, text] of Object.entries(outputs)) {
  const full = join(ROOT, path);
  if (check) {
    if (!existsSync(full) || readFileSync(full, 'utf8') !== text) stale.push(path);
  } else writeFileSync(full, text);
}
if (stale.length) {
  console.error(`out of date: ${stale.join(', ')} (run node tools/make-app-data.mjs)`);
  process.exit(1);
}
